export const clampPanelHeight=value=>Math.max(320,Math.min(1600,Number(value)||600));
export function mountPanelWindows(root,onResize){
 const panels=[root.querySelector('#editor-detail'),root.querySelector('.dependency-panel')],names=['计算建模','计算依赖图'];let full=null,drag=null,frame=0;
 let sharedHeight;
 const setHeight=value=>{sharedHeight=clampPanelHeight(value);root.style.setProperty('--workspace-panel-height',sharedHeight+'px');panels.forEach(p=>p.style.removeProperty('--panel-height'));};
 const persistHeight=()=>{try{localStorage.setItem('forge-workspace-panel-height',sharedHeight);}catch{}};
 try{const saved=localStorage.getItem('forge-workspace-panel-height');const legacy=[0,1].map(i=>Number(localStorage.getItem('forge-panel-height-'+i))).filter(h=>h>0);if(saved)setHeight(saved);else if(legacy.length)setHeight(Math.max(...legacy));}catch{}

 const resize=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(onResize);};
 function controls(){panels.forEach((p,i)=>{const heading=p.querySelector(i?'.section-heading':'.detail-heading');if(!heading)return;const old=p.querySelector('[data-editor="toggle-flow-fullscreen"]');if(old)old.remove();let actions=heading.querySelector('.panel-window-actions');if(!actions){actions=document.createElement('div');actions.className='panel-window-actions';actions.innerHTML=`<button type="button" class="btn" data-panel-min="${i}"></button><button type="button" class="btn" data-panel-full="${i}"></button>`;heading.append(actions);}if(i===1){const add=heading.querySelector('[data-editor="add"]');if(add&&add.parentElement!==actions)actions.prepend(add);}const minimized=p.classList.contains('workspace-panel-minimized');for(const [selector,text,label]of [['[data-panel-min]',minimized?'▱ 恢复':'− 最小化',minimized?'恢复'+names[i]:'最小化'+names[i]],['[data-panel-full]',full===p?'⤢ 恢复':'⛶ 全屏',full===p?'恢复'+names[i]+'布局':'全屏'+names[i]]]){const b=actions.querySelector(selector);if(b.textContent!==text)b.textContent=text;b.setAttribute('aria-label',label);b.setAttribute('aria-pressed',String(selector==='[data-panel-min]'?minimized:full===p));}
 if(!p.querySelector('.panel-height-resizer')){const h=document.createElement('div');h.className='panel-height-resizer';h.tabIndex=0;h.setAttribute('role','separator');h.setAttribute('aria-orientation','horizontal');h.setAttribute('aria-label','同时调整建模和计算依赖图高度');h.dataset.panelHeight=i;h.innerHTML='<span></span>';p.append(h);}});}
 function restore(){if(!full)return;full.classList.remove('workspace-panel-fullscreen');full=null;document.body.classList.remove('workspace-panel-fullscreen-active');}
 function click(e){const min=e.target.closest('[data-panel-min]'),expand=e.target.closest('[data-panel-full]');if(!min&&!expand)return;const i=Number((min||expand).dataset[min?'panelMin':'panelFull']),p=panels[i];if(min){if(full===p)restore();p.classList.toggle('workspace-panel-minimized');}else{const wasFull=full===p;restore();if(!wasFull){full=p;p.classList.remove('workspace-panel-minimized');p.classList.add('workspace-panel-fullscreen');document.body.classList.add('workspace-panel-fullscreen-active');const side=document.querySelector('.sidebar');root.style.setProperty('--panel-shell-left',(side?.getBoundingClientRect().right||0)+'px');}}controls();resize();}
 const down=e=>{const h=e.target.closest('[data-panel-height]');if(!h||e.button!==0)return;const i=Number(h.dataset.panelHeight),p=panels[i];if(full||p.classList.contains('workspace-panel-minimized'))return;e.preventDefault();drag={i,y:e.clientY,height:p.getBoundingClientRect().height,handle:h};h.setPointerCapture(e.pointerId);root.classList.add('is-panel-resizing');};
 const move=e=>{if(!drag)return;setHeight(drag.height+e.clientY-drag.y);};
 const finish=()=>{if(!drag)return;persistHeight();drag=null;root.classList.remove('is-panel-resizing');resize();};
 const key=e=>{if(e.key==='Escape'&&full){restore();controls();resize();}const h=e.target.closest('[data-panel-height]');if(!h||full||!['ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();const p=panels[Number(h.dataset.panelHeight)];setHeight(e.key==='Home'?600:p.getBoundingClientRect().height+(e.key==='ArrowUp'?-24:24));persistHeight();resize();};

 const shellResize=()=>{if(full)root.style.setProperty('--panel-shell-left',(document.querySelector('.sidebar')?.getBoundingClientRect().right||0)+'px');};window.addEventListener('forge:sidebar-resize',shellResize);window.addEventListener('resize',shellResize);
 root.addEventListener('click',click);root.addEventListener('pointerdown',down);root.addEventListener('pointermove',move);root.addEventListener('pointerup',finish);root.addEventListener('pointercancel',finish);document.addEventListener('keydown',key);const observer=new MutationObserver(controls);panels.forEach(p=>observer.observe(p,{childList:true,subtree:true}));controls();
 return ()=>{window.removeEventListener('forge:sidebar-resize',shellResize);window.removeEventListener('resize',shellResize);observer.disconnect();cancelAnimationFrame(frame);restore();root.removeEventListener('click',click);root.removeEventListener('pointerdown',down);root.removeEventListener('pointermove',move);root.removeEventListener('pointerup',finish);root.removeEventListener('pointercancel',finish);document.removeEventListener('keydown',key);};
}
